/// <summary>
/// Provides conversions between Celsius and Fahrenheit temperature scales.
/// </summary>
public static class TemperatureConverter

/// <summary>
/// Converts a temperature expressed in degrees Celsius to degrees Fahrenheit.
/// </summary>
/// <param name="celsius">The temperature in degrees Celsius.</param>
/// <returns>The equivalent temperature in degrees Fahrenheit.</returns>
public static decimal CelsiusToFahrenheit(decimal celsius)

/// <summary>
/// Converts a temperature expressed in degrees Fahrenheit to degrees Celsius.
/// </summary>
/// <param name="fahrenheit">The temperature in degrees Fahrenheit.</param>
/// <returns>The equivalent temperature in degrees Celsius.</returns>
public static decimal FahrenheitToCelsius(decimal fahrenheit)
